import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"A docs app that renders docs/ with VitePress","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/2026-10-03-docs-app.md","filePath":"decisions/2026-10-03-docs-app.md"}`),a={name:`decisions/2026-10-03-docs-app.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="a-docs-app-that-renders-docs-with-vitepress" tabindex="-1" dir="auto">A docs app that renders <code>docs/</code> with VitePress <a class="header-anchor" href="#a-docs-app-that-renders-docs-with-vitepress" aria-label="Permalink to “A docs app that renders docs/ with VitePress”">​</a></h1><ul><li dir="auto">Status: accepted</li><li dir="auto">Date: 2026-10-03</li></ul><h2 id="context" tabindex="-1" dir="auto">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p dir="auto">The architecture, conventions, pipeline, security and decision documents live in <code>docs/</code> as Markdown, read on GitHub. We want them as a searchable, RTL Hebrew site next to the product site and Storybook, without moving or copying the files: they stay where agents and humans already look for them.</p><h2 id="decision" tabindex="-1" dir="auto">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li dir="auto"><code>apps/docs</code> (project <code>docs</code>, tags <code>type:app</code> <code>scope:product</code>) is a <a href="https://vitepress.dev" target="_blank" rel="noreferrer">VitePress</a> site whose <code>srcDir</code> is the repo&#39;s <code>docs/</code>. It renders the files; it stores no content.</li><li dir="auto">It is deployed at <code>/docs/</code> by <code>tools/pages</code>, next to <code>/</code> (site) and <code>/storybook/</code>. <code>pages:build</code> builds it with <code>site</code> and <code>ui</code>, and <code>assemble.mjs</code> copies it into the artifact. <code>docs/</code> is a reserved top-level path, and the artifact may never contain a top-level <code>pr-&lt;n&gt;/</code>: the root publish of <code>deploy.yml</code> replaces everything on <code>gh-pages</code> except <code>pr-*/</code>, so previews are untouched and <code>deploy.yml</code> itself did not change.</li><li dir="auto"><strong>VitePress <code>2.0.0-alpha.20</code>, pinned.</strong> The stable 1.6 line depends on Vite 5 and esbuild 0.21, which add four advisories (one high) to <code>pnpm audit</code> (D1, D2-T). The 2.x line uses the Vite 8 the repo already runs. Revisit when 2.0 is stable; Dependabot does not move a pinned prerelease.</li><li dir="auto">Other additions: <code>postcss-rtlcss</code> (the RTL support VitePress documents; the default theme is written for LTR) and <code>vue</code> (the pages VitePress compiles from <code>docs/*.md</code> sit outside <code>apps/docs</code>, so they cannot reach VitePress&#39;s own copy; listed in <code>knip.ts</code>).</li><li dir="auto">Not an alternative: a React + Vite renderer would reuse more of the stack, but search, syntax highlighting, outline, sidebar and 404 handling are the code we would then own.</li><li dir="auto">The app is hand-made, not generated: <code>pnpm new:app</code> creates React/Vite apps. Its Nx <code>build</code> and <code>dev</code> targets are <code>nx:run-commands</code>, so A7 requires them, and the <code>pages:build</code> change, in <code>tools/security/tasks.json</code> (reviewed).</li><li dir="auto">The Hebrew UI (navigation, search, labels) is configured in <code>apps/docs/src/labels.ts</code>. The sidebar is built from the files in <code>docs/</code> (<code>src/sidebar.ts</code>); a new file appears without config. The landing page is <code>docs/index.md</code>. Each block takes the direction of its own text (<code>dir=&quot;auto&quot;</code>), because the documents are English and Hebrew prose in one RTL site, and code stays left-to-right.</li><li dir="auto">Links from <code>docs/</code> to files outside it (<code>../tools/...</code>) become links to the file on GitHub (<code>GITHUB_REPOSITORY</code>, or a GitHub <code>origin</code>), or plain text when the repository is unknown. Dead links elsewhere fail the build.</li></ul><h2 id="consequences" tabindex="-1" dir="auto">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li dir="auto">Raw HTML in a document can break the docs build (<code>&lt;stage&gt;</code> at the start of a line is HTML to Vue). <code>src/docs-content.spec.ts</code> names the file and line; put such text in backticks that do not wrap before it.</li><li dir="auto">Mermaid blocks render as code; there is no diagram plugin.</li><li dir="auto"><code>pipeline-map.md</code> is generated; the docs site shows whatever is committed.</li><li dir="auto">The docs content is English, so only the chrome is Hebrew until the documents are translated.</li></ul>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};